    a_intervals = sorted([interval for interval in a if interval[0] < interval[1]])
    b_intervals = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_intervals:
        return []

    # Merge overlapping/touching intervals in a
    merged_a = []
    for start, end in a_intervals:
        if merged_a and merged_a[-1][1] >= start:
            merged_a[-1][1] = max(merged_a[-1][1], end)
        else:
            merged_a.append([start, end])

    # Merge overlapping/touching intervals in b
    merged_b = []
    for start, end in b_intervals:
        if merged_b and merged_b[-1][1] >= start:
            merged_b[-1][1] = max(merged_b[-1][1], end)
        else:
            merged_b.append([start, end])

    # Subtract b from a
    result = []
    for a_start, a_end in merged_a:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in merged_b:
            new_ranges = []
            for curr_start, curr_end in current_ranges:
                # No overlap
                if curr_end <= b_start or curr_start >= b_end:
                    new_ranges.append([curr_start, curr_end])
                else:
                    # Overlap exists
                    # Keep part before b_start
                    if curr_start < b_start:
                        new_ranges.append([curr_start, b_start])
                    # Keep part after b_end
                    if curr_end > b_end:
                        new_ranges.append([b_end, curr_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Merge touching intervals in result
    result.sort()
    merged_result = []
    for start, end in result:
        if merged_result and merged_result[-1][1] >= start:
            merged_result[-1][1] = max(merged_result[-1][1], end)
        else:
            merged_result.append([start, end])

    return merged_result

